"""Integer lattice evaluation for one installation setup.

The public entry point ``setup_ranges`` checks whether a fixed selection of
board settings admits at least one integer displacement vector satisfying the
global bounds, common physical constraints, setup constraints, and setup
readings.  If it does, it returns the inclusive integer extrema of every gauge
over all such vectors.

The small input limits make exhaustive enumeration the simplest correct
strategy.  To avoid re-enumerating the lattice once for every board-selection
candidate, non-reading feasibility is cached per ``(request, setup)`` pair.
Reading feasibility is stored as bitsets so a candidate selection is just a
handful of C-level bitwise intersections.
"""

import json
from array import array
from itertools import product


# Position of every set bit in a byte, used to enumerate bitset members.
_BIT_POSITIONS = tuple(
    tuple(bit for bit in range(8) if (value >> bit) & 1)
    for value in range(256)
)


class _Lattice:
    __slots__ = (
        "count",
        "all_mask",
        "reading_masks",
        "setting_lookup",
        "gauge_ids",
        "gauge_values",
        "base_ranges",
    )

    def __init__(
        self,
        count,
        reading_masks,
        setting_lookup,
        gauge_ids,
        gauge_values,
        base_ranges,
    ):
        self.count = count
        self.all_mask = (1 << count) - 1 if count else 0
        self.reading_masks = reading_masks
        self.setting_lookup = setting_lookup
        self.gauge_ids = gauge_ids
        self.gauge_values = gauge_values
        self.base_ranges = base_ranges


def _compact_terms(dimensions, coefficients, offset=0):
    """Return ``(offset, nonzero_terms)`` where terms are (dimension, coefficient)."""
    terms = tuple(
        (index, coefficient)
        for index, dimension in enumerate(dimensions)
        if (coefficient := coefficients.get(dimension, 0)) != 0
    )
    return offset, terms


def _eval_compact(offset, terms, vector):
    total = offset
    for index, coefficient in terms:
        total += coefficient * vector[index]
    return total


def _build_lattice(request, setup, use_list_gauge=False):
    dimensions = list(request["bounds"].keys())
    intervals = []
    total_vectors = 1
    for dimension in dimensions:
        low, high = request["bounds"][dimension]
        intervals.append(range(low, high + 1))
        total_vectors *= high - low + 1

    physical_constraints = request.get("physical_constraints", [])
    constraints = physical_constraints + setup.get("constraints", [])

    constraint_terms = []
    for constraint in constraints:
        offset, terms = _compact_terms(
            dimensions, constraint.get("coefficients", {}), 0
        )
        constraint_terms.append((offset, terms, constraint["min"], constraint["max"]))

    boards_by_id = {board["id"]: board for board in request.get("boards", [])}
    readings = setup.get("readings", [])

    # For every reading, pre-compute the linear form for every board setting.
    # Masks are indexed as reading_masks[reading_index][setting_index].
    reading_info = []
    reading_masks_bytes = []
    setting_lookup = {}
    for reading in readings:
        board = boards_by_id[reading["board"]]
        settings = board.get("settings", [])
        row = []
        lookup = setting_lookup.setdefault(reading["board"], {})
        for setting_index, setting in enumerate(settings):
            lookup[setting["id"]] = setting_index
            channel = setting["channels"][reading["channel"]]
            offset, terms = _compact_terms(
                dimensions, channel.get("coefficients", {}), channel.get("offset", 0)
            )
            row.append((offset, terms, reading["raw"][0], reading["raw"][1]))
        reading_info.append(row)
        reading_masks_bytes.append([
            bytearray((total_vectors + 7) // 8) for _ in settings
        ])

    gauges = request.get("gauges", [])
    gauge_ids = [gauge["id"] for gauge in gauges]
    gauge_info = []
    for gauge in gauges:
        offset, terms = _compact_terms(
            dimensions, gauge.get("coefficients", {}), gauge.get("base", 0)
        )
        gauge_info.append((offset, terms))

    need_gauge_values = bool(readings)
    if need_gauge_values:
        gauge_values = [[] for _ in gauges] if use_list_gauge else [array("q") for _ in gauges]
    else:
        gauge_values = []
    base_min = [None] * len(gauges)
    base_max = [None] * len(gauges)

    candidate_count = 0
    for vector in product(*intervals):
        feasible = True
        for offset, terms, low, high in constraint_terms:
            value = _eval_compact(offset, terms, vector)
            if value < low or value > high:
                feasible = False
                break
        if not feasible:
            continue

        position = candidate_count
        candidate_count += 1

        for gauge_index, (offset, terms) in enumerate(gauge_info):
            value = _eval_compact(offset, terms, vector)
            if need_gauge_values:
                gauge_values[gauge_index].append(value)
            if base_min[gauge_index] is None or value < base_min[gauge_index]:
                base_min[gauge_index] = value
            if base_max[gauge_index] is None or value > base_max[gauge_index]:
                base_max[gauge_index] = value

        if readings:
            byte_index, bit_index = divmod(position, 8)
            bit = 1 << bit_index
            for reading_index, row in enumerate(reading_info):
                masks_for_settings = reading_masks_bytes[reading_index]
                for setting_index, (offset, terms, low, high) in enumerate(row):
                    value = _eval_compact(offset, terms, vector)
                    if low <= value <= high:
                        masks_for_settings[setting_index][byte_index] |= bit

    if readings:
        reading_masks = [
            [
                int.from_bytes(bytes(mask_bytes), "little")
                for mask_bytes in row
            ]
            for row in reading_masks_bytes
        ]
    else:
        reading_masks = []

    if candidate_count:
        base_ranges = {
            gauge_ids[index]: [base_min[index], base_max[index]]
            for index in range(len(gauge_ids))
        }
    else:
        base_ranges = None

    return _Lattice(
        candidate_count,
        reading_masks,
        setting_lookup,
        gauge_ids,
        gauge_values,
        base_ranges,
    )


_lattice_cache = {}


def _freeze(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _get_lattice(request, setup):
    key = (_freeze(request), _freeze(setup))
    lattice = _lattice_cache.get(key)
    if lattice is None:
        try:
            lattice = _build_lattice(request, setup)
        except OverflowError:
            lattice = _build_lattice(request, setup, use_list_gauge=True)
        _lattice_cache[key] = lattice
    return lattice


def _ranges_from_mask(lattice, mask):
    if mask == lattice.all_mask:
        return {
            gauge_id: list(interval)
            for gauge_id, interval in lattice.base_ranges.items()
        }

    result = {
        gauge_id: [None, None]
        for gauge_id in lattice.gauge_ids
    }

    data = mask.to_bytes((mask.bit_length() + 7) // 8, "little")
    for byte_index, byte in enumerate(data):
        if not byte:
            continue
        base_position = byte_index * 8
        for offset in _BIT_POSITIONS[byte]:
            position = base_position + offset
            for gauge_index, gauge_id in enumerate(lattice.gauge_ids):
                value = lattice.gauge_values[gauge_index][position]
                interval = result[gauge_id]
                if interval[0] is None or value < interval[0]:
                    interval[0] = value
                if interval[1] is None or value > interval[1]:
                    interval[1] = value

    return result


def setup_ranges(request, setup, chosen):
    """Return gauge extrema for a fixed selection, or None when infeasible."""
    lattice = _get_lattice(request, setup)
    if lattice.count == 0 or lattice.base_ranges is None:
        return None

    mask = lattice.all_mask
    for reading_index, reading in enumerate(setup.get("readings", [])):
        board_id = reading["board"]
        setting = chosen.get(board_id)
        if setting is None:
            return None
        setting_index = lattice.setting_lookup[board_id][setting["id"]]
        mask &= lattice.reading_masks[reading_index][setting_index]
        if not mask:
            return None

    return _ranges_from_mask(lattice, mask)

from itertools import product

from runtime import build, read

from .board_calibration import compatible_settings
from .setup_lattice import setup_ranges


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]

    compatible = compatible_settings(request)
    boards = request.get("boards", [])
    board_ids = [board["id"] for board in boards]
    setting_lists = [compatible[board_id] for board_id in board_ids]

    minimum_cost = None
    optimal = []

    for combination in product(*setting_lists):
        cost = sum(setting["penalty"] for setting in combination)
        if minimum_cost is not None and cost > minimum_cost:
            continue

        chosen = dict(zip(board_ids, combination))
        setup_results = {}
        feasible = True
        for setup in request.get("setups", []):
            ranges = setup_ranges(request, setup, chosen)
            if ranges is None:
                feasible = False
                break
            setup_results[setup["id"]] = ranges

        if not feasible:
            continue

        if minimum_cost is None or cost < minimum_cost:
            minimum_cost = cost
            optimal = [(combination, setup_results)]
        else:
            optimal.append((combination, setup_results))

    if minimum_cost is None:
        return {
            "minimum_cost": None,
            "setting_options": {},
            "ranges": {},
        }

    setting_options = {}
    for board_index, board in enumerate(boards):
        board_id = board["id"]
        order = [setting["id"] for setting in board.get("settings", [])]
        present = set()
        for combination, _ in optimal:
            present.add(combination[board_index]["id"])
        setting_options[board_id] = [
            setting_id for setting_id in order if setting_id in present
        ]

    ranges = {}
    for setup in request.get("setups", []):
        setup_id = setup["id"]
        gauge_ids = [gauge["id"] for gauge in request.get("gauges", [])]
        setup_range_values = {gauge_id: [None, None] for gauge_id in gauge_ids}
        for _, setup_results in optimal:
            for gauge_id in gauge_ids:
                low, high = setup_results[setup_id][gauge_id]
                if setup_range_values[gauge_id][0] is None or low < setup_range_values[gauge_id][0]:
                    setup_range_values[gauge_id][0] = low
                if setup_range_values[gauge_id][1] is None or high > setup_range_values[gauge_id][1]:
                    setup_range_values[gauge_id][1] = high
        ranges[setup_id] = setup_range_values

    return {
        "minimum_cost": minimum_cost,
        "setting_options": setting_options,
        "ranges": ranges,
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

def _linear_value(expr, x):
    """Evaluate offset + sum(coefficients[d] * x[d]) with missing terms zero."""
    total = expr.get("offset", 0)
    coefficients = expr.get("coefficients", {})
    for datum, coefficient in coefficients.items():
        total += coefficient * x[datum]
    return total


def compatible_settings(request):
    """Return board_id -> list of settings satisfying every calibration."""
    calibrations_by_board = {}
    for calibration in request.get("calibrations", []):
        calibrations_by_board.setdefault(calibration["board"], []).append(calibration)

    result = {}
    for board in request.get("boards", []):
        board_id = board["id"]
        calibrations = calibrations_by_board.get(board_id, [])
        feasible = []
        for setting in board.get("settings", []):
            channels = setting.get("channels", {})
            ok = True
            for calibration in calibrations:
                channel = channels.get(calibration["channel"])
                if channel is None:
                    ok = False
                    break
                reading = _linear_value(channel, calibration["displacements"])
                low, high = calibration["raw"]
                if not (low <= reading <= high):
                    ok = False
                    break
            if ok:
                feasible.append(setting)
        result[board_id] = feasible

    return result

