import json
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
PUBLIC_REQUEST = json.loads((ROOT / "inputs/request.json").read_text(encoding="utf-8"))
PUBLIC_EXPECTED = json.loads((ROOT / "public_expected.json").read_text(encoding="utf-8"))


API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": "packages/analysis/engine.py",
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": False,
                "contract_path": "packages/analysis/SPEC.md",
                "requirement_quote": "All coefficients, offsets, raw readings and costs are finite integers.",
                "reason": "The visible specification only constrains valid domain inputs; it does not state that an unknown field carrying a non-finite value must raise ValueError.",
            },
            "invalid_payload_type": {
                "applicable": False,
                "contract_path": "packages/analysis/SPEC.md",
                "requirement_quote": "All references, channel IDs and datum names in a request are valid.",
                "reason": "The visible specification assumes a valid request object and does not document ValueError behavior for a non-object payload.",
            },
        },
    }
]


class PublicBusinessReportTests(unittest.TestCase):
    def test_public_example_direct_transform(self):
        # Output-contract check: complete JSON report matches the worked example.
        result = call_candidate(
            "packages/analysis/engine.py",
            "transform",
            args=[{"request": PUBLIC_REQUEST}, {}],
        )
        self.assertEqual(result, PUBLIC_EXPECTED)

    def test_calibration_ignores_installation_physical_constraints(self):
        # SPEC: calibration pieces serve only as known observations.
        request = {
            "bounds": {"x": [0, 4]},
            "physical_constraints": [
                {"coefficients": {"x": 1}, "min": 1, "max": 1}
            ],
            "boards": [
                {
                    "id": "A",
                    "settings": [
                        {"id": "s1", "penalty": 0, "channels": {"c": {"coefficients": {"x": 1}, "offset": 1}}},
                        {"id": "s2", "penalty": 0, "channels": {"c": {"coefficients": {"x": 1}, "offset": 0}}},
                        {"id": "s3", "penalty": 1, "channels": {"c": {"coefficients": {"x": 1}, "offset": 2}}},
                    ],
                }
            ],
            "calibrations": [
                {"board": "A", "channel": "c", "displacements": {"x": 2}, "raw": [3, 4]}
            ],
            "setups": [],
            "gauges": [],
        }
        result = call_candidate(
            "packages/analysis/board_calibration.py",
            "compatible_settings",
            args=[request],
        )
        self.assertEqual([setting["id"] for setting in result["A"]], ["s1", "s3"])

    def test_setup_ranges_integer_extrema(self):
        # SPEC: exact integer extrema, not a continuous relaxation.
        request = {
            "bounds": {"x": [0, 2], "y": [0, 2]},
            "physical_constraints": [
                {"coefficients": {"x": 1, "y": 1}, "min": 1, "max": 2}
            ],
            "boards": [
                {
                    "id": "A",
                    "settings": [
                        {"id": "a", "penalty": 0, "channels": {"c": {"coefficients": {"x": 2}, "offset": 0}}}
                    ],
                }
            ],
            "calibrations": [],
            "setups": [
                {"id": "s", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [2, 2]}]}
            ],
            "gauges": [
                {"id": "sum", "base": 0, "coefficients": {"x": 1, "y": 1}},
                {"id": "difference", "base": 0, "coefficients": {"x": 1, "y": -1}},
            ],
        }
        chosen = {"A": request["boards"][0]["settings"][0]}
        result = call_candidate(
            "packages/analysis/setup_lattice.py",
            "setup_ranges",
            args=[request, request["setups"][0], chosen],
        )
        self.assertEqual(result, {"sum": [1, 2], "difference": [0, 1]})

    def test_setup_ranges_returns_none_without_integer_solution(self):
        # SPEC: feasibility is decided on the integer lattice, not by rounding.
        request = {
            "bounds": {"x": [0, 2], "y": [0, 2]},
            "physical_constraints": [
                {"coefficients": {"x": 1, "y": 1}, "min": 1, "max": 2}
            ],
            "boards": [
                {
                    "id": "A",
                    "settings": [
                        {"id": "a", "penalty": 0, "channels": {"c": {"coefficients": {"x": 2}, "offset": 0}}}
                    ],
                }
            ],
            "calibrations": [],
            "setups": [
                {"id": "s", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [1, 1]}]}
            ],
            "gauges": [
                {"id": "sum", "base": 0, "coefficients": {"x": 1, "y": 1}},
            ],
        }
        chosen = {"A": request["boards"][0]["settings"][0]}
        result = call_candidate(
            "packages/analysis/setup_lattice.py",
            "setup_ranges",
            args=[request, request["setups"][0], chosen],
        )
        self.assertIsNone(result)

    def test_no_shared_selection_returns_empty_report(self):
        # SPEC: if no shared selection makes every setup feasible, return null cost.
        request = {
            "bounds": {"x": [0, 0]},
            "physical_constraints": [],
            "boards": [
                {
                    "id": "A",
                    "settings": [
                        {"id": "a0", "penalty": 0, "channels": {"c": {"coefficients": {}, "offset": 0}}},
                        {"id": "a1", "penalty": 1, "channels": {"c": {"coefficients": {}, "offset": 1}}},
                    ],
                }
            ],
            "calibrations": [],
            "setups": [
                {"id": "s0", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [0, 0]}]},
                {"id": "s1", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [1, 1]}]},
            ],
            "gauges": [{"id": "g", "base": 0, "coefficients": {"x": 1}}],
        }
        result = call_candidate(
            "packages/analysis/engine.py",
            "transform",
            args=[{"request": request}, {}],
        )
        self.assertEqual(
            result,
            {"minimum_cost": None, "setting_options": {}, "ranges": {}},
        )


if __name__ == "__main__":
    unittest.main()
